{
"html": "<div data-ui-unit="E2" class="e2-root">
    <label class="e2-label">멘토 검색</label>
    <div class="e2-search-surface">
        <svg class="e2-icon" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
        </svg>
        <input id="search" type="text" placeholder="멘토 또는 회사를 검색하세요" disabled />
    </div>
</div>",
"css": "[data-ui-unit="E2"] {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.e2-label {
  color: var(--ink, #283548);
  font-family: "Noto Sans KR", sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 1.57;
  margin-bottom: 8px;
}

.e2-search-surface {
  display: flex;
  align-items: center;
  background-color: var(--surface, #fff);
  border-radius: 12px;
  min-height: 46px;
  padding: 0 16px;
}

.e2-icon {
  color: var(--muted, #566273);
  flex-shrink: 0;
}

#search {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  padding: 0;
  margin-left: 12px;
  color: var(--ink, #283548);
  font-family: "Noto Sans KR", sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 1.57;
}

#search::placeholder {
  color: var(--muted, #566273);
  opacity: 1;
}

#search:disabled {
  background-color: transparent;
  color: var(--ink, #283548);
  -webkit-text-fill-color: var(--ink, #283548);
  cursor: default;
}"
}
